use std::alloc::{GlobalAlloc,Layout,System};use std::sync::atomic::AtomicUsize;
static LIVE:AtomicUsize=AtomicUsize::new(0);static PEAK:AtomicUsize=AtomicUsize::new(0);
fn add(n:usize){let v=LIVE.fetch_add(n,Ordering::Relaxed)+n;PEAK.fetch_max(v,Ordering::Relaxed);}
struct Tracking;unsafe impl GlobalAlloc for Tracking{unsafe fn alloc(&self,l:Layout)->*mut u8{let p=unsafe{System.alloc(l)};if !p.is_null(){add(l.size());}p}unsafe fn dealloc(&self,p:*mut u8,l:Layout){LIVE.fetch_sub(l.size(),Ordering::Relaxed);unsafe{System.dealloc(p,l)}}unsafe fn realloc(&self,p:*mut u8,l:Layout,n:usize)->*mut u8{let q=unsafe{System.realloc(p,l,n)};if !q.is_null(){LIVE.fetch_sub(l.size(),Ordering::Relaxed);add(n);}q}}#[global_allocator]static ALLOC:Tracking=Tracking;
static ROOT:std::sync::OnceLock<std::path::PathBuf>=std::sync::OnceLock::new();fn project()->&'static Path{ROOT.get().unwrap().as_path()}
