 let trace=LoadTrace::default();let cancel=AtomicBool::new(false);let baseline=LIVE.load(Ordering::Relaxed);PEAK.store(baseline,Ordering::Relaxed);let assets=CityAssets::load_catalog(i,2,527,Default::default(),&cancel,&trace).unwrap();let peak=PEAK.load(Ordering::Relaxed)-baseline;let metrics=assets.metrics();assert_eq!(metrics.source_references,362852);assert_eq!(metrics.decoded_bytes,10920960);assert_eq!(metrics.non_floor_references,215396);assert_eq!(metrics.row_item_bytes,12);assert_eq!(metrics.index_payload_capacity_bytes,2584752);assert!(metrics.index_payload_capacity_bytes<=INDEX_PAYLOAD_LIMIT);let r=probe["results"].as_array().unwrap().iter().find(|r|r["map_id"]==527).unwrap();let mut frames=Vec::new();
 for v in r["images"].as_array().unwrap(){let camera=CameraRect{x:v["camera"][0].as_i64().unwrap()as i32,y:v["camera"][1].as_i64().unwrap()as i32,width:800,height:600};let(c,f)=assets.render_measured(camera,&cancel).unwrap();assert_eq!(c.rgba(),pixels(Path::new(v["image"]["path"].as_str().unwrap())));let path=root.join(format!("cpu-direct-row-527-{}.png",v["name"].as_str().unwrap()));let mut e=png::Encoder::new(fs::File::create(&path).unwrap(),800,600);e.set_color(png::ColorType::Rgba);e.set_depth(png::BitDepth::Eight);e.write_header().unwrap().write_image_data(c.rgba()).unwrap();let b=fs::read(&path).unwrap();images.push(json!({"identity":[2,527],"profile":"generic_catalog_row_direct","name":v["name"],"camera":v["camera"],"image":{"path":path,"bytes":b.len(),"sha256":format!("{:X}",Sha256::digest(b)),"rgba_sha256":format!("{:X}",Sha256::digest(c.rgba()))}}));frames.push(json!({"name":v["name"],"metrics":f}));}
 assert!(assets.render_with_fragment_limit(assets.initial_camera(),1,&cancel).is_err());*negative+=1;assert!(assets.render_with_fragment_limit(assets.initial_camera(),FRAME_FRAGMENT_LIMIT+1,&cancel).is_err());*negative+=1;assert!(assets.render(assets.initial_camera(),&AtomicBool::new(true)).is_err());*negative+=1;
 let before=LIVE.load(Ordering::Relaxed);drop(assets);let freed=before-LIVE.load(Ordering::Relaxed);assert!(freed>metrics.decoded_bytes+metrics.index_payload_capacity_bytes);
