 let p=project();let root=p.join("target/r484-remaining-batch");let i=input("r484-map-binding.json");let m:Value=serde_json::from_slice(&fs::read(&i.manifest).unwrap()).unwrap();let(_,plans,rows)=native_multisector_resources::load(&i).unwrap();let ids=[(0u8,566u32),(0,570),(2,554),(2,513),(2,527),(2,518),(2,521),(2,522),(5,532),(5,512),(5,517),(5,524),(5,530)];assert_eq!(plans.len(),37);assert_eq!(rows.len(),40);assert_eq!(plans[24..].iter().map(|b|(b.mode,b.plan.map_id)).collect::<Vec<_>>(),ids);assert_eq!(plans[24..].iter().map(|b|b.plan.sectors.len()).sum::<usize>(),115);
