  for reference in r["images"].as_array().unwrap(){let c=&reference["camera"];let(cx,cy)=(c[0].as_i64().unwrap() as i32,c[1].as_i64().unwrap() as i32);let current=rt.frame().unwrap().camera();if(current.x,current.y)!=(cx,cy){rt.handle(Action::Pan(cx-current.x,cy-current.y)).unwrap();wait(||{rt.poll();!rt.pan_pending()});}if let Some(old)=held.take(){assert!(old.bgra().is_err());negative+=1;}let f=rt.frame().unwrap();assert_eq!(f.identity(),(mode,id));assert_eq!((f.camera().x,f.camera().y),(cx,cy));let name=reference["name"].as_str().unwrap();let image=save(&root.join(format!("cpu-{mode}-{id}-{name}.png")),&f);assert_eq!(pixels(Path::new(image["path"].as_str().unwrap())),pixels(Path::new(reference["image"]["path"].as_str().unwrap())));images.push(json!({"identity":[mode,id],"name":name,"camera":c,"image":image}));held=Some(f);}
  let b=&r["bounds"];for(dx,dy,x,y)in[(i32::MIN,i32::MIN,b[0].as_i64().unwrap() as i32,b[1].as_i64().unwrap() as i32),(i32::MAX,i32::MAX,b[2].as_i64().unwrap() as i32-800,b[3].as_i64().unwrap() as i32-600)]{rt.handle(Action::Pan(dx,dy)).unwrap();wait(||{rt.poll();!rt.pan_pending()});let c=rt.frame().unwrap().camera();assert_eq!((c.x,c.y),(x,y));negative+=1;}
  let produced=rt.progress().frames_produced.load(Ordering::Acquire);rt.handle(Action::Pan(-48,-24)).unwrap();wait(||rt.progress().frames_produced.load(Ordering::Acquire)>produced);let old=rt.frame().unwrap();let stale=rt.stale_results_rejected;choose(&mut rt,next_mode,next_id);assert!(old.bgra().is_err());rt.poll();assert_eq!(rt.stale_results_rejected,stale+1);assert!(rt.frame().is_none());negative+=2;
