  records.push(json!({"identity":[mode,id],"next_identity":[next_mode,next_id],"source_sectors":plans[24+k].plan.sectors.len(),"anchor":r["anchor"],"bounds":r["bounds"],"budget":r["budget"],"seam":r["seam"],"profile":if id==527{"generic_rows"}else{"unchanged_regular"},"actual_load_and_five_player_frames":true,"wrong_mode_same_ID_refusal_keeps_current_frame":true,"queued_load_and_pan_cross_mode_or_map_rejected":true,"actual_active_load_Back_cancel_switch_no_frame":true}));
